#include <iostream>
#include <array>
#include <span>
int countPositive(std::span<const int> values) {
    int count{};
    for (int value : values) { if (value > 0) { ++count; } }
    return count;
}
int main() {
    std::array<int, 1> zero{0};
    std::array<int, 1> negative{-1};
    std::array<int, 3> mixed{-2, 0, 4};
    std::array<int, 3> positive{1, 2, 3};
    int failures{};
    if (countPositive(std::span<const int>{}) != 0) { ++failures; }
    if (countPositive(zero) != 0) { ++failures; }
    if (countPositive(negative) != 0) { ++failures; }
    if (countPositive(mixed) != 1) { ++failures; }
    if (countPositive(positive) != 3) { ++failures; }
    if (failures != 0) { std::cout << "FAIL\n"; return 1; }
    std::cout << "PASS 5\n";
}
